  "P0299": {"title":"Turbo/supercharger underboost","causes":"Boost leak, control solenoid, wastegate, turbo or sensor issue.","symptoms":"Symptoms depend on the underlying fault; possible examples include a warning light, rough running, poor economy, hesitation, hard starting or reduced power.","checks":"Inspect boost hoses and clamps; test control system and sensor data.","prevention":"Maintain oil and air systems.","note":"Do not condemn turbo from code alone.","type":"generic","repair":"Fix leaks, wiring and connector faults first; replace a sensor or component only after it fails testing. Repair only what testing confirms (wiring, connector, leak or failed part), then clear the code and verify with a road test and live data."},
  "P0300": {"title":"Random/multiple cylinder misfire","causes":"Ignition, fuel, vacuum leak, compression, timing or sensor issue.","symptoms":"Symptoms depend on the underlying fault; possible examples include a warning light, rough running, poor economy, hesitation, hard starting or reduced power.","checks":"Check freeze-frame data, plugs/coils, intake leaks, fuel delivery and compression as needed.","prevention":"Service ignition parts and fix leaks.","note":"If light flashes or engine shakes severely, stop driving.","type":"generic","repair":"Repair the confirmed ignition, fuel or mechanical cause on the affected cylinder(s). Repair only what testing confirms (wiring, connector, leak or failed part), then clear the code and verify with a road test and live data."},
  "P0301": {"title":"Cylinder 1 misfire","causes":"Plug, coil, injector, compression, wiring or air leak at cylinder 1.","symptoms":"Symptoms depend on the underlying fault; possible examples include a warning light, rough running, poor economy, hesitation, hard starting or reduced power.","checks":"Inspect plug/coil and wiring; check injector, leaks and compression as needed.","prevention":"Maintain ignition system and repair leaks.","note":"Generic meaning is broadly shared; cylinder 1 location varies.","type":"generic","repair":"Repair the confirmed ignition, fuel or mechanical cause on the affected cylinder(s). Repair only what testing confirms (wiring, connector, leak or failed part), then clear the code and verify with a road test and live data."},
  "P0302": {"title":"Cylinder 2 misfire","causes":"Plug, coil, injector, wiring, compression or air leak.","symptoms":"Symptoms depend on the underlying fault; possible examples include a warning light, rough running, poor economy, hesitation, hard starting or reduced power.","checks":"Inspect ignition, injector circuit and compression as needed.","prevention":"Maintain ignition and fuel systems.","note":"Cylinder numbering varies.","type":"generic","repair":"Repair the confirmed ignition, fuel or mechanical cause on the affected cylinder(s). Repair only what testing confirms (wiring, connector, leak or failed part), then clear the code and verify with a road test and live data."},
